<template><view class="page"><view class="custom-nav" :style="{ paddingTop: statusBarHeight + 'px' }"><view class="nav-row"><text class="nav-icon" @click="goBack">←</text><text class="nav-title">文件单位</text><text class="nav-icon empty"> </text></view></view><view class="content"><input class="fs-input" v-model="inputVal" type="digit" placeholder="输入字芢数..." /><view class="fs-results"><view class="fs-item" v-for="u in units" :key="u.name"><text class="fs-name">{{ u.name }}</text><text class="fs-val">{{ (inputVal / u.factor).toFixed(4) }}</text></view></view></view></view></template><script setup>import { ref, computed, onMounted } from "vue"
